PY_BLOCK = '\n\n# =============================================================================\n#  S771_ORTHOTIC_BILLS (Session 423, 10-Nov-2026; D886; the owner\'s mock approved 11:27 IST, "go")\n#  THE ORTHOTIC BILLS CARD on the Stock check hub -- each bill of the section\'s dealers (section_dealers: Yuvika today), the\n#  scan\'s lines (assets.db bill_items, READ ONLY) beside the bill\'s own Marg lines (purchase_line, the newest export that carries\n#  the bill), paired one to one. A line is judged by size, side (left / right), brand and quantity:\n#    * a scan word the reader got wrong (no size, two sizes, \'V\', \'St\', \'MN\') takes the size of the Marg line it pairs with -- a note;\n#    * a quantity that differs while the line\'s amount is the same on both sides is the reader\'s misread -- a note;\n#    * a Marg line with no scan line is a difference only when the two totals differ (otherwise the reader missed a line -- a note).\n#  A differing line stays highlighted -- and its bill flagged, kept on the card past its month -- until the next Marg export\n#  shows it fixed (the line is then no longer different) or the doctor clears it ("Marg is right"). "Amir fixes Marg" puts ONE\n#  tap job on Amir\'s card (amir_job, kind \'tap\', as S768 does). An item with an open difference gets a star at the next count\n#  of the section (start(): bill_flags beside the doctor\'s marks, the hand changes and the record).\n#  THE OVERFLOW READ (F-1233): Marg\'s item-wise export prints a long bill number into the item column (\'06202627CAST SHOE M\n#  TYNOR\', bill number empty). Such lines are read here for the bill whose number ends in that prefix (or starts the item), the\n#  prefix cut off -- a READ only; the reader\'s own repair is its own kit.\n#  The scanned bill opens folded on the card: /scanapp/bills/<id>/file (the Scan App\'s own route and its own access rule).\n#  Writes: section_bill_mark (its own table) and amir_job \'tap\' rows. Nothing writes to Marg, purchase_line or assets.db.\n# =============================================================================\nBILLS_SINCE = "2026-09-01"                                    # the first month with scanned dealer bills\nASSETS_DB = os.environ.get("ASSETS_DB", "/root/assetapp/assets.db")\nSCAN_URL = "/scanapp/bills/%d/file"\nBILLS_BY = "S771"\nDDL_S771 = (\n    "CREATE TABLE IF NOT EXISTS section_bill_mark (bill_id INTEGER NOT NULL, dkey TEXT NOT NULL, action TEXT NOT NULL, item TEXT,"\n    " why TEXT, by_user TEXT, at TEXT NOT NULL, job_key TEXT, PRIMARY KEY (bill_id, dkey))",\n)\n_SIDES = {"RT": "Right", "RIGHT": "Right", "LF": "Left", "LT": "Left", "LEFT": "Left"}\n_BRANDS = {"TYNOR": "Tynor", "TY": "Tynor", "UNISON": "Unison", "UNISEX": "Unison", "UNIS": "Unison", "UNI": "Unison",\n           "BAMBOO": "Bamboo", "HOSPIKIT": "Hospikit", "HOSPIK": "Hospikit", "HOSPITIK": "Hospikit", "DYNA": "Dyna", "HOPE": "Hope",\n           "FLAMINGO": "Flamingo", "BLING": "Bling", "VISSCO": "Vissco"}\n_CANON = {"COLLER": "COLLAR", "SUPP": "SUPPORT", "SPL": "SPLINT", "IMMOBILIZER": "IMMOB", "IMMOBILISER": "IMMOB", "IMMOBILISE": "IMMOB",\n          "IMMOBILIZE": "IMMOB", "CONST": "CONT", "CLAVICLE": "CLAVICAL", "ELASTI": "ELASTIC", "ELAS": "ELASTIC", "UNIV": "UNIVERSAL",\n          "GREY": "GRAY", "G": "GRAY", "BRACE": "BRACE"}\n_NOISE = {"T", "ADJ", "NEO", "LONG", "THE", "FOR", "WITH", "UNK", "ST", "V", "MN", "NAG", "PCS"}\n\n\ndef ensure_s771(con):\n    for ddl in DDL_S771:\n        con.execute(ddl)\n\n\ndef _acon():\n    """assets.db READ ONLY; None when it cannot be read (the card then says the scans could not be read)."""\n    try:\n        if not os.path.exists(ASSETS_DB):\n            return None\n        a = sqlite3.connect("file:%s?mode=ro" % ASSETS_DB, uri=True, timeout=2)\n        a.row_factory = sqlite3.Row\n        a.execute("SELECT 1 FROM bills LIMIT 1")\n        return a\n    except Exception:                                          # noqa: BLE001\n        return None\n\n\ndef parse_name(name):\n    """dict(size, size_raw, side, brand, words) of a scan or Marg item name. size \'\' = none read, \'?\' = unreadable or two sizes."""\n    up = str(name or "").upper()\n    up = re.sub(r"\\bL\\s*\\.?\\s*S\\b\\.?", " LS ", up)            # \'L.S. BELT\' / \'L S BELT\' is lumbo-sacral, never two sizes\n    toks = [t for t in re.split(r"[^A-Z0-9]+", up) if t]\n    sizes = [t for t in toks if t in SIZE_TOKENS]\n    side = ""\n    brand = ""\n    words = []\n    for t in toks:\n        if t in SIZE_TOKENS:\n            continue\n        if t in _SIDES:\n            side = _SIDES[t]\n            continue\n        if t in _BRANDS:\n            brand = _BRANDS[t]\n            continue\n        if t in _NOISE or t.isdigit():\n            continue\n        words.append(_CANON.get(t, t))\n    if len(set(sizes)) == 1:\n        size = sizes[0]\n    elif len(set(sizes)) > 1:\n        size = "?"\n    else:\n        size = ""\n    raw = ""\n    m = re.search(r"[-(]\\s*\\(?\\s*([A-Z0-9/ ]{1,5}?)\\s*\\)?\\s*\\.?$", str(name or "").upper().strip())\n    if m:\n        raw = m.group(1).strip()\n    if not size and raw and raw not in ("UNIV", "UNIVERSAL") and raw not in _BRANDS:\n        size = "?"\n    return dict(size=size, size_raw=raw, side=side, brand=brand, words=words)\n\n\ndef _wsim(a, b):\n    """How alike two word lists are: words equal or one a prefix of the other (3+ letters)."""\n    if not a or not b:\n        return 0.0\n    used, hit = set(), 0\n    for x in a:\n        for j, y in enumerate(b):\n            if j in used:\n                continue\n            if x == y or (min(len(x), len(y)) >= 3 and (x.startswith(y) or y.startswith(x))):\n                used.add(j)\n                hit += 1\n                break\n    return hit / float(max(len(a), len(b)))\n\n\ndef _f(v):\n    try:\n        return float(v)\n    except (TypeError, ValueError):\n        return None\n\n\ndef _pair_score(s, m):\n    ps, pm = s["p"], m["p"]\n    sc = _wsim(ps["words"], pm["words"])\n    if sc < 0.3:\n        return None\n    if ps["size"] not in ("", "?") and pm["size"] not in ("", "?"):\n        sc += 0.3 if ps["size"] == pm["size"] else -0.3\n    if ps["side"] and pm["side"]:\n        sc += 0.3 if ps["side"] == pm["side"] else -0.3\n    if ps["brand"] and pm["brand"]:\n        sc += 0.2 if ps["brand"] == pm["brand"] else -0.2\n    sr, mr, mu = _f(s["rate"]), _f(m["rate"]), _f(m["unit_net"])\n    if sr and ((mr and abs(sr - mr) <= max(0.02 * mr, 0.05)) or (mu and abs(sr - mu) <= max(0.02 * mu, 0.05))):\n        sc += 0.4\n    if s["qty"] is not None and m["qty"] is not None and abs(s["qty"] - m["qty"]) < 0.001:\n        sc += 0.1\n    return sc\n\n\ndef pair_lines(scan, marg):\n    """[(scan_line | None, marg_line | None)] one to one, the best pairs first."""\n    cand = []\n    for i, s in enumerate(scan):\n        for j, m in enumerate(marg):\n            sc = _pair_score(s, m)\n            if sc is not None:\n                cand.append((sc, i, j))\n    cand.sort(key=lambda x: (-x[0], x[1], x[2]))\n    si, mj, out = set(), set(), []\n    for sc, i, j in cand:\n        if i in si or j in mj:\n            continue\n        si.add(i)\n        mj.add(j)\n        out.append((i, j))\n    for i, s in enumerate(scan):                               # leftovers: a badly read name, paired by its amount or rate alone\n        if i in si:\n            continue\n        for j, m in enumerate(marg):\n            if j in mj:\n                continue\n            sa, ma, sr, mu = _f(s["amount"]), _f(m["amount_net"]), _f(s["rate"]), _f(m["unit_net"])\n            if (sa and ma and abs(sa - ma) <= 1.0) or (sr and mu and abs(sr - mu) <= max(0.01 * mu, 0.05) and s["qty"] == m["qty"]):\n                si.add(i)\n                mj.add(j)\n                out.append((i, j))\n                break\n    pairs = [(scan[i], marg[j]) for i, j in sorted(out)]\n    pairs += [(s, None) for i, s in enumerate(scan) if i not in si]\n    pairs += [(None, m) for j, m in enumerate(marg) if j not in mj]\n    return pairs\n\n\ndef _num(q):\n    q = _f(q)\n    if q is None:\n        return None\n    return int(q) if abs(q - round(q)) < 0.001 else round(q, 2)\n\n\ndef judge(s, m, totals_agree):\n    """(kind, why_en, note_en): kind \'\' when the line agrees."""\n    if s and not m:\n        if totals_agree:\n            return "", "", "No Marg line matched this reading; the totals agree"\n        return "missing_marg", "Not in Marg: the bill has it, Marg does not", ""\n    if m and not s:\n        if totals_agree:\n            return "", "", "The reader missed this line on the scan; the totals agree"\n        return "missing_bill", "Not on the bill: Marg has it, the scanned bill does not", ""\n    ps, pm = s["p"], m["p"]\n    notes = []\n    if ps["size"] not in ("", "?") and pm["size"] not in ("", "?") and ps["size"] != pm["size"]:\n        return "size", "Size: the bill says %s, Marg has %s" % (ps["size"], pm["size"]), ""\n    if ps["side"] and pm["side"] and ps["side"] != pm["side"]:\n        return "side", "Side: the bill says %s, Marg has %s" % (ps["side"], pm["side"]), ""\n    if ps["brand"] and pm["brand"] and ps["brand"] != pm["brand"]:\n        return "brand", "Brand: the bill says %s, Marg has %s" % (ps["brand"], pm["brand"]), ""\n    if ps["size"] == "?" and pm["size"] not in ("", "?"):\n        notes.append(\'"%s" is the reader\\\'s misread of %s\' % (ps["size_raw"] or "?", pm["size"]))\n    if s["qty"] is not None and m["qty"] is not None and abs(s["qty"] - m["qty"]) > 0.001:\n        sa, ma = _f(s["amount"]), _f(m["amount_net"])\n        if sa is not None and ma is not None and abs(sa - ma) <= 2.0:\n            notes.append("Read as %s; the line is \\u20b9%s on both \\u2014 %s" % (_num(s["qty"]), "{:,.0f}".format(ma), "one piece" if _num(m["qty"]) == 1 else "%s pieces" % _num(m["qty"])))\n            return "", "", "; ".join(notes)\n        return "qty", "Quantity: the bill says %s, Marg has %s" % (_num(s["qty"]), _num(m["qty"])), "; ".join(notes)\n    return "", "", "; ".join(notes)\n\n\ndef _dkey(kind, s, m, seen):\n    """kind | scan name | Marg name | the two quantities | which occurrence -- a changed figure is a new difference, two alike stay two."""\n    base = "%s|%s|%s|%s|%s" % (kind, nk((s or {}).get("name") or ""), nk((m or {}).get("name") or ""), _num((s or {}).get("qty")), _num((m or {}).get("qty")))\n    seen[base] = seen.get(base, 0) + 1\n    return "%s|%d" % (base, seen[base])\n\n\ndef _stamps(con, md5s, bill_date):\n    """md5 -> export_stamp for the exports whose period covers the bill\'s date (an unknown export: \'\' -- it still counts)."""\n    out = {m: "" for m in md5s}\n    if md5s and _table(con, "purchase_export"):\n        for md5, stamp, pf, pt in con.execute("SELECT md5, export_stamp, period_from, period_to FROM purchase_export WHERE md5 IN (%s)"\n                                              % ",".join("?" * len(md5s)), list(md5s)):\n            if bill_date and pf and pt and not (pf <= bill_date <= pt):\n                out.pop(md5, None)\n            else:\n                out[md5] = stamp or ""\n    return out\n\n\ndef _spilled(con, bill):\n    """F-1233: {md5: [lines]} whose bill number spilled into the item column -- THIS bill\'s (its whole number, or a tail of 6+ that\n    begins with a digit and is followed by a letter), the number cut off."""\n    bno = re.sub(r"[^A-Za-z0-9_]", "", str(bill["bill_no"] or ""))\n    if len(bno) < 6:\n        return {}\n    per = {}\n    for r in con.execute("SELECT id, item, qty, free, rate_p, net_amount_p, source_md5 FROM purchase_line WHERE supplier_norm=? AND bill_no IS NULL "\n                         "AND direction=\'PURCHASE\' ORDER BY id", (bill["supplier_norm"],)):\n        it = str(r["item"] or "")\n        cut = 0\n        if it.upper().startswith(bno.upper()):\n            cut = len(bno)\n        else:\n            for k in range(len(bno) - 1, 5, -1):\n                tail = bno[-k:]\n                if tail[0].isdigit() and it.upper().startswith(tail.upper()) and len(it) > k and not it[k].isdigit():\n                    cut = k\n                    break\n        name = it[cut:].lstrip("_ ").strip() if cut else ""\n        if name:\n            per.setdefault(r["source_md5"], []).append(dict(r, item=name))\n    return per\n\n\ndef bill_lines(con, bill):\n    """(lines, spilled): Marg\'s lines of one bill from the NEWEST export that carries it (by its export stamp), whether that export\n    printed the bill properly or spilled its number into the item column."""\n    per = {}\n    for r in con.execute("SELECT id, item, qty, free, rate_p, net_amount_p, source_md5 FROM purchase_line WHERE supplier_norm=? AND bill_no=? "\n                         "AND bill_date=? AND direction=\'PURCHASE\' ORDER BY id", (bill["supplier_norm"], bill["bill_no"], bill["bill_date"])):\n        per.setdefault(r["source_md5"], []).append(dict(r))\n    proper = set(per)\n    sp = _spilled(con, bill)\n    st = _stamps(con, set(sp), bill["bill_date"])\n    for md5, rows in sp.items():\n        if md5 in st and md5 not in per:\n            per[md5] = rows\n    if not per:\n        return [], False\n    st_all = _stamps(con, set(per), None)\n    newest = max(per, key=lambda k: (st_all.get(k, ""), max(x["id"] for x in per[k])))\n    out = []\n    for x in per[newest]:\n        q = (_f(x["qty"]) or 0.0) + (_f(x["free"]) or 0.0)\n        net = (_f(x["net_amount_p"]) or 0.0) / 100.0\n        out.append(dict(name=x["item"], qty=q, rate=(_f(x["rate_p"]) or 0.0) / 100.0, amount_net=net, unit_net=(net / q) if q else None,\n                        p=parse_name(x["item"])))\n    return out, newest not in proper\n\n\ndef _scan_of(con, acon, bill_id):\n    r = con.execute("SELECT asset_bill_id FROM purchase_scan_link WHERE bill_id=?", (bill_id,)).fetchone() if _table(con, "purchase_scan_link") else None\n    if not r or acon is None:\n        return None\n    b = acon.execute("SELECT id, vendor, bill_no, bill_date, total_amount, source_stored, source_orig FROM bills WHERE id=?", (r[0],)).fetchone()\n    if not b:\n        return None\n    items = [dict(name=i["item_name"], qty=_f(i["quantity"]), rate=_f(i["rate"]), amount=_f(i["amount"]), p=parse_name(i["item_name"]))\n             for i in acon.execute("SELECT item_name, quantity, rate, amount FROM bill_items WHERE bill_id=? ORDER BY id", (b["id"],))]\n    orig = str(b["source_orig"] or "").lower()\n    kind = "pdf" if orig.endswith(".pdf") else ("image" if re.search(r"\\.(jpe?g|png|webp|gif|heic)$", orig) else "file")\n    return dict(id=b["id"], bill_no=b["bill_no"], total=_f(b["total_amount"]), items=items, has_file=bool(b["source_stored"]), kind=kind)\n\n\ndef _marks(con, bill_id):\n    return {r["dkey"]: dict(action=r["action"], by=r["by_user"], at=r["at"]) for r in\n            con.execute("SELECT dkey, action, by_user, at FROM section_bill_mark WHERE bill_id=?", (bill_id,))}\n\n\ndef one_bill(con, acon, bill):\n    """The card\'s row for one bill: state agrees | differs | no_marg | no_scan | no_scan_lines, and its lines."""\n    sc = _scan_of(con, acon, bill["id"])\n    ml, over = bill_lines(con, bill)\n    marg_total = (bill["amount_p"] or 0) / 100.0\n    x = dict(id=bill["id"], no=str(bill["bill_no"] or ""), date=bill["bill_date"], dealer=bill["supplier"] or bill["supplier_norm"],\n             marg_total=marg_total, scan_total=(sc or {}).get("total"), scan_id=(sc or {}).get("id"), scan_no=(sc or {}).get("bill_no") or "",\n             scan_kind=(sc or {}).get("kind"), scan_url=(SCAN_URL % sc["id"]) if sc and sc.get("has_file") else "", overflow=over, lines=[], open=0, with_amir=0)\n    if not sc:\n        x["state"] = "no_scan"\n        x["lines"] = [dict(scan="", sq=None, marg=m["name"], mq=_num(m["qty"]), kind="", why="", note="", key="") for m in ml]\n        return x\n    if not sc["items"]:\n        x["state"] = "no_scan_lines"\n        return x\n    if not ml:\n        x["state"] = "no_marg"\n        x["lines"] = [dict(scan=s["name"], sq=_num(s["qty"]), marg="", mq=None, kind="", why="", note="", key="") for s in sc["items"]]\n        return x\n    agree = sc["total"] is not None and abs(sc["total"] - marg_total) <= 2.0\n    mk = _marks(con, bill["id"])\n    seen = {}\n    for s, m in pair_lines(sc["items"], ml):\n        kind, why, note = judge(s, m, agree)\n        key = _dkey(kind, s, m, seen) if kind else ""\n        mark = mk.get(key) if key else None\n        line = dict(scan=(s or {}).get("name") or "", sq=_num((s or {}).get("qty")), marg=(m or {}).get("name") or "", mq=_num((m or {}).get("qty")),\n                    kind=kind, why=why, note=note, key=key, mark=mark)\n        if kind and not (mark and mark["action"] == "clear"):\n            x["open"] += 1\n            if mark and mark["action"] == "amir":\n                x["with_amir"] += 1\n        x["lines"].append(line)\n    x["state"] = "differs" if x["open"] else "agrees"\n    return x\n\n\ndef bills_card(con, section, today=None):\n    today = today or dt.date.today()\n    month = today.strftime("%Y-%m")\n    dealers = sorted(section_dealers(con, section))\n    if not dealers:\n        return dict(section=section, month=month, dealers=[], now=[], open=[], settled=[], scans_ok=True)\n    acon = _acon()\n    try:\n        rows = con.execute("SELECT * FROM purchase_bill WHERE supplier_norm IN (%s) AND bill_date >= ? ORDER BY bill_date DESC, id DESC"\n                           % ",".join("?" * len(dealers)), dealers + [BILLS_SINCE]).fetchall()\n        now, older, settled = [], [], []\n        for b in rows:\n            x = one_bill(con, acon, b)\n            if str(b["bill_date"] or "")[:7] == month:\n                now.append(x)\n            elif x["state"] in ("differs", "no_marg"):\n                older.append(x)\n            elif x["state"] == "agrees":\n                settled.append(dict(id=x["id"], no=x["no"], date=x["date"]))\n    finally:\n        if acon is not None:\n            acon.close()\n    return dict(section=section, month=month, dealers=dealers, now=now, open=older, settled=settled, scans_ok=acon is not None)\n\n\ndef bill_flags(con, section, items):\n    """item -> (1, why): a Marg item named on an open (not cleared) differing line of the card -- starred at the next count."""\n    out = {}\n    try:\n        ensure_s771(con)\n        card = bills_card(con, section)\n    except Exception:                                          # noqa: BLE001 -- the marks never stop a count\n        return out\n    for x in card["now"] + card["open"]:\n        for l in x["lines"]:\n            if not l.get("kind") or (l.get("mark") or {}).get("action") == "clear":\n                continue\n            why = "Bill %s of %s: %s" % (x["no"], ddmon(x["date"]), l["why"])\n            for nm in (l["marg"], l["scan"]):\n                if not nm:\n                    continue\n                hit = next((it for it in items if same_item(it, nm)), None) if nm == l["marg"] else _item_like(items, l["scan"])\n                if hit and hit not in out:\n                    out[hit] = (1, why)\n    return out\n\n\ndef _item_like(items, scan_name):\n    """The section item a scan line names (size, side and brand all as read), or None."""\n    p = parse_name(scan_name)\n    if p["size"] in ("", "?") and not p["side"]:\n        return None\n    best, bs = None, 0.0\n    for it in items:\n        q = parse_name(it)\n        if (p["size"] not in ("", "?") and q["size"] != p["size"]) or (p["side"] and q["side"] != p["side"]) or \\\n                (p["brand"] and q["brand"] and q["brand"] != p["brand"]):\n            continue\n        s = _wsim(p["words"], q["words"])\n        if s > bs:\n            best, bs = it, s\n    return best if bs >= 0.6 else None\n\n\n_AMIR_HI = {"size": "bill par size %(s)s hai, Marg mein %(m)s chadha hai",\n            "side": "bill par %(s)s hai, Marg mein %(m)s chadha hai",\n            "brand": "bill par %(s)s company hai, Marg mein %(m)s chadha hai",\n            "qty": "bill par %(s)s nag hai, Marg mein %(m)s nag chadhe hain",\n            "missing_marg": "bill par hai, Marg mein nahi chadha",\n            "missing_bill": "Marg mein hai, bill par nahi hai"}\n_SIDE_HI = {"Right": "RT (daayaan)", "Left": "LF (baayaan)"}\n\n\ndef _amir_text(kind, line):\n    ps, pm = parse_name(line["scan"]), parse_name(line["marg"])\n    s = {"size": ps["size"], "side": _SIDE_HI.get(ps["side"], ps["side"]), "brand": ps["brand"], "qty": line["sq"]}.get(kind, "")\n    m = {"size": pm["size"], "side": _SIDE_HI.get(pm["side"], pm["side"]), "brand": pm["brand"], "qty": line["mq"]}.get(kind, "")\n    return _AMIR_HI.get(kind, "bill aur Marg alag hain") % dict(s=s, m=m)\n\n\ndef mark(con, bill_id, key, action, user):\n    """(ok, payload | message, http). action: amir (one tap job on Amir\'s card) | clear (Marg is right) | undo."""\n    ensure_s771(con)\n    b = con.execute("SELECT * FROM purchase_bill WHERE id=?", (bill_id,)).fetchone()\n    if not b:\n        return False, "No such bill.", 404\n    acon = _acon()\n    try:\n        x = one_bill(con, acon, b)\n    finally:\n        if acon is not None:\n            acon.close()\n    line = next((l for l in x["lines"] if key and l.get("kind") and l.get("key") == key), None)\n    have = con.execute("SELECT action, job_key FROM section_bill_mark WHERE bill_id=? AND dkey=?", (bill_id, key)).fetchone()\n    if action == "undo":\n        if not have:\n            return False, "Nothing to undo on that line.", 409\n        con.execute("DELETE FROM section_bill_mark WHERE bill_id=? AND dkey=?", (bill_id, key))\n        if have["job_key"] and _table(con, "amir_job"):            # a job Amir has not done yet leaves his card with the mark\n            con.execute("DELETE FROM amir_job WHERE key=? AND done_at IS NULL", (have["job_key"],))\n        audit(con, None, "bill_undo", dict(bill=bill_id, key=key, was=have["action"]), user)\n        con.commit()\n        return True, dict(message="Undone."), 200\n    if not line:\n        return False, "That line no longer differs -- the card was out of date. It is read again now.", 409\n    if have:\n        return False, "That line is already %s." % ("with Amir" if have["action"] == "amir" else "cleared"), 409\n    ts = now_iso()\n    job = None\n    if action == "amir":\n        if not _table(con, "amir_job"):\n            return False, "Amir\'s card is not on this server.", 503\n        job = "S771:b%d:%s:%s" % (bill_id, hashlib_md5(key)[:10], re.sub(r"\\D", "", ts))\n        dealer = str(b["supplier"] or b["supplier_norm"] or "").title()\n        con.execute("INSERT OR IGNORE INTO amir_job (key, kind, subject, text_hi, sub_hi, created_at, created_by, show_from) VALUES (?,?,?,?,?,?,?,?)",\n                    (job, "tap", line["marg"] or line["scan"],\n                     "%s — %s. Marg ki entry theek kijiye." % (line["marg"] or line["scan"], _amir_text(line["kind"], line)),\n                     "%s bill %s · %s · Dr sahab ne bill se milaya" % (dealer, b["bill_no"], ddmon(b["bill_date"])),\n                     ts.replace("T", " "), BILLS_BY, ts.replace("T", " ")))\n    elif action != "clear":\n        return False, "Unknown action.", 400\n    try:\n        con.execute("INSERT INTO section_bill_mark (bill_id, dkey, action, item, why, by_user, at, job_key) VALUES (?,?,?,?,?,?,?,?)",\n                    (bill_id, key, action, line["marg"] or line["scan"], line["why"], user, ts, job))\n    except sqlite3.IntegrityError:                             # another screen settled the same line a moment ago\n        con.rollback()\n        return False, "That line was settled on another screen a moment ago.", 409\n    audit(con, None, "bill_" + action, dict(bill=bill_id, key=key, why=line["why"], job=job), user)\n    con.commit()\n    return True, dict(message="On Amir\'s card. The line clears by itself when the next Marg export shows the fix." if action == "amir"\n                      else "Cleared: Marg is right for this line."), 200\n\n\ndef hashlib_md5(s):\n    import hashlib                                             # noqa: PLC0415\n    return hashlib.md5(str(s).encode("utf-8")).hexdigest()\n\n\n@bp.route(P + "/api/bills")\ndef api_bills():\n    u, con, own, err = _auth()\n    if err:\n        return err\n    if not own:\n        return _refuse("The doctor\'s card.", 403)\n    sec = str(request.args.get("section") or "Orthotics")\n    if sec not in COUNT_SECTIONS:\n        return _refuse("This card is for: %s." % ", ".join(COUNT_SECTIONS), 400)\n    ensure_s771(con)\n    return jsonify(ok=True, **bills_card(con, sec))\n\n\n@bp.route(P + "/api/bills/mark", methods=["POST"])\ndef api_bills_mark():\n    u, con, own, err = _auth()\n    if err:\n        return err\n    if not own:\n        return _refuse("Only the doctor settles a bill\'s line.", 403)\n    b = _body()\n    try:\n        bid = int(b.get("bill"))\n    except (TypeError, ValueError):\n        return _refuse("Which bill?", 400)\n    ok, res, code = mark(con, bid, str(b.get("key") or ""), str(b.get("action") or ""), _who(u))\n    if not ok:\n        return _refuse(res, code)\n    return jsonify(ok=True, **res)\n# ---- S771_ORTHOTIC_BILLS end ------------------------------------------------------------------------------------------------------\n'
CSS_BLOCK = '/* S771_ORTHOTIC_BILLS: the Orthotic bills card (the owner\'s mock of 10-Nov, approved 11:27) */\n#s771 .s771card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px 16px;margin-top:10px}\n#s771 .s771top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start}\n#s771 .s771tally{display:flex;gap:8px;flex-wrap:wrap}\n#s771 .s771tally span{background:var(--surface-2);border-radius:10px;padding:6px 10px;font-size:13.5px;color:var(--ink-2)}\n#s771 .s771tally b{font-size:16px;color:var(--ink);font-variant-numeric:tabular-nums}\n#s771 .s771tally .d{background:var(--diff-soft);color:var(--diff)} #s771 .s771tally .d b{color:var(--diff)}\n#s771 .s771sect{font-size:12.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);margin:16px 0 6px}\n#s771 details.s771b{border:1px solid var(--line);border-radius:12px;margin:8px 0;background:var(--surface)}\n#s771 details.s771b.flag{border-left:4px solid var(--diff)}\n#s771 details.s771b>summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:auto auto minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:10px 12px;font-size:14.5px}\n#s771 details>summary::-webkit-details-marker{display:none}\n#s771 details>summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:12px}\n#s771 .d8{color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap} #s771 .bn{font-weight:700;white-space:nowrap}\n#s771 .dl{color:var(--ink-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap} #s771 .ln{color:var(--muted);font-size:13px;white-space:nowrap}\n#s771 .chip{font-size:12px;font-weight:700;border-radius:999px;padding:2px 10px;white-space:nowrap}\n#s771 .chip.ok{background:var(--accent-soft);color:var(--ok)} #s771 .chip.diff{background:var(--diff-soft);color:var(--diff)} #s771 .chip.warn{background:var(--warn-soft);color:var(--warn)}\n#s771 .in{padding:0 12px 12px;overflow-x:auto}\n#s771 table.s771t{width:100%;border-collapse:collapse;font-size:14px;table-layout:fixed}\n#s771 table.s771t th{text-align:left;font-size:12px;color:var(--muted);font-weight:700;padding:6px;border-bottom:1.5px solid var(--line)}\n#s771 table.s771t td{padding:8px 6px;border-bottom:1px solid var(--line);vertical-align:top}\n#s771 table.s771t .num{text-align:right;font-variant-numeric:tabular-nums} #s771 table.s771t td.num{font-weight:700}\n#s771 .nm{font-weight:600;overflow-wrap:anywhere}\n#s771 table.s771t td.mg{padding-left:16px} #s771 tr.d{background:var(--diff-soft)} #s771 tr.d td.mg .nm{color:var(--diff)} #s771 tr.d:not(.dx) td{border-bottom:0} #s771 tr.dx td{padding-top:0}\n#s771 tr.cl td{color:var(--muted)}\n#s771 .why{font-size:13px;font-weight:700;color:var(--diff);margin-top:3px} #s771 .note{font-size:12px;color:var(--muted);margin-top:2px}\n#s771 .act{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:6px}\n#s771 .act .b{min-height:40px;font-size:13.5px;padding:6px 11px} #s771 .act .b.ghost{border-color:var(--muted)}\n#s771 .act .said{font-size:13px;font-weight:700;color:var(--ink-2)} #s771 .act a.u{display:inline-block;padding:9px 12px;min-height:40px;font-size:13.5px;color:var(--ink-2);text-decoration:underline;cursor:pointer}\n#s771 .star{font-size:13px;color:var(--ink-2)}\n#s771 .hold{background:var(--warn-soft);color:var(--warn);border-radius:10px;padding:9px 11px;font-size:13.5px;font-weight:600;margin:4px 0 8px}\n#s771 .foot{font-size:13px;color:var(--ink-2);margin-top:6px}\n#s771 details.s771scan{margin-top:10px;border:1px dashed var(--line);border-radius:10px}\n#s771 details.s771scan>summary{cursor:pointer;padding:8px 10px;font-size:14px;font-weight:700;color:var(--accent);list-style:none}\n#s771 .s771paper{padding:0 10px 10px} #s771 .s771paper .pic{max-height:70vh;overflow:auto;border-radius:8px} #s771 .s771paper img{max-width:100%;height:auto;display:block}\n#s771 .s771paper iframe{width:100%;height:75vh;border:1px solid var(--line);border-radius:8px;background:#fff}\n#s771 .legend{margin-top:14px;padding-top:10px;border-top:1px solid var(--line);font-size:13px;color:var(--ink-2)}\n@media (max-width:640px){\n #s771 details.s771b>summary{grid-template-columns:auto minmax(0,1fr) auto;row-gap:2px} #s771 .bn{white-space:normal;overflow-wrap:anywhere;min-width:0} #s771 .dl{grid-column:1/-1;order:5} #s771 .ln{display:none}\n #s771 table.s771t colgroup,#s771 table.s771t thead{display:none}\n #s771 table.s771t tr{display:grid;grid-template-columns:1fr auto;border-bottom:1.5px solid var(--line);padding:4px 0}\n #s771 table.s771t tr.d:not(.dx){border-bottom:0} #s771 table.s771t td{border-bottom:0;padding:4px 6px}\n #s771 table.s771t td.sc::before{content:"BILL";display:block;font-size:10.5px;font-weight:700;letter-spacing:.06em;color:var(--muted)}\n #s771 table.s771t td.mg::before{content:"MARG";display:block;font-size:10.5px;font-weight:700;letter-spacing:.06em;color:var(--muted)}\n #s771 table.s771t td.mg,#s771 table.s771t td.mq{border-top:1px dashed var(--line)}\n #s771 table.s771t td.sq,#s771 table.s771t td.mq{align-self:start;padding-top:20px}\n #s771 tr.dx td{grid-column:1/-1} #s771 .act{flex-direction:column;align-items:stretch} #s771 .act .b{width:100%;min-height:44px}\n #s771 .s771paper iframe{height:60vh}\n}\n'
JS_BLOCK = '\n/* ---- S771_ORTHOTIC_BILLS (10-Nov-2026, the owner\'s mock approved 11:27 IST): each orthotics dealer\'s bill -- the scan beside\n   its Marg lines; a differing line stays highlighted (and its bill on the card) until the next Marg export shows it fixed or\n   the doctor clears it; "Amir fixes Marg" puts one tap job on Amir\'s card; the scanned bill opens folded, loaded only on a tap. ---- */\nlet S771=null; const S771OPEN={};\nfunction s771mon(m){ const d=new Date(String(m||"")+"-01T00:00:00"); return isNaN(d)?esc(m||""):d.toLocaleDateString("en-GB",{month:"long",year:"numeric"}); }\nfunction s771rs(v){ return v==null?"-":"₹"+Number(v).toLocaleString("en-IN",{maximumFractionDigits:0}); }\nfunction s771chip(x){\n  if(x.state==="no_marg") return \'<span class="chip warn">Marg lines not here yet</span>\';\n  if(x.state==="no_scan") return \'<span class="chip warn">Not scanned yet</span>\';\n  if(x.state==="no_scan_lines") return \'<span class="chip warn">Scan not read yet</span>\';\n  if(!x.open) return \'<span class="chip ok">Agrees</span>\';\n  return \'<span class="chip diff">\'+x.open+\' line\'+(x.open===1?\' differs\':\'s differ\')+\'</span>\';\n}\nfunction s771line(x,l){\n  const d=!!l.kind, cl=d&&l.mark&&l.mark.action==="clear";\n  let h=\'<tr class="\'+(d&&!cl?\'d\':(cl?\'cl\':\'\'))+\'"><td class="sc"><div class="nm">\'+(l.scan?esc(l.scan):\'— not on the scan\')+\'</div>\'+(l.note?\'<div class="note">\'+esc(l.note)+\'</div>\':\'\')\n    +\'</td><td class="num sq">\'+(l.sq==null?\'\':esc(l.sq))+\'</td><td class="mg"><div class="nm">\'+(l.marg?esc(l.marg):\'— not in Marg\')+\'</div></td><td class="num mq">\'+(l.mq==null?\'\':esc(l.mq))+\'</td></tr>\';\n  if(!d) return h;\n  const k=\' data-s771bill="\'+x.id+\'" data-s771key="\'+esc(l.key)+\'"\';\n  let act;\n  if(cl) act=\'<span class="said">Cleared by you (\'+esc(s769dd(l.mark.at))+\') — Marg is right</span><a class="u" href="#" role="button" data-s771act="undo"\'+k+\'>Undo</a>\';\n  else if(l.mark&&l.mark.action==="amir") act=\'<span class="said">On Amir\\\'s card since \'+esc(s769dd(l.mark.at))+\' — clears by itself when the next Marg export shows the fix</span><a class="u" href="#" role="button" data-s771act="undo"\'+k+\'>Undo</a>\';\n  else act=\'<button class="b main" data-s771act="amir"\'+k+\'>Amir fixes Marg</button><button class="b ghost" data-s771act="clear"\'+k+\'>Marg is right — clear</button><span class="star">★ starred at the next \'+esc(S771.section)+\' count</span>\';\n  return h+\'<tr class="\'+(cl?\'cl\':\'d\')+\' dx"><td colspan="4">\'+(cl?\'\':\'<div class="why">\'+esc(l.why)+\'</div>\')+\'<div class="act">\'+act+\'</div></td></tr>\';\n}\nfunction s771bill(x){\n  const flag=x.open||x.state==="no_marg";\n  const head=\'<summary><span class="d8">\'+esc(s769dd(x.date))+\'</span><span class="bn">Bill \'+esc(x.no)+\'</span><span class="dl">\'+esc(x.dealer)+\'</span>\'\n    +\'<span class="ln">\'+x.lines.length+\' line\'+(x.lines.length===1?\'\':\'s\')+\' · \'+s771rs(x.scan_total!=null?x.scan_total:x.marg_total)+\'</span>\'+s771chip(x)+\'</summary>\';\n  let body=\'\';\n  if(x.state==="no_marg") body=\'<div class="hold">The scan is read (\'+x.lines.length+\' lines), but Marg\\\'s item lines for this bill are not on the server yet — only its total. The next item-wise purchase export brings them; the card compares it then by itself.</div>\';\n  else if(x.state==="no_scan") body=\'<div class="hold">This bill has no scan linked yet. Once it is scanned, its lines are compared here by themselves.</div>\';\n  else if(x.state==="no_scan_lines") body=\'<div class="hold">The scan is here but its lines are not read yet.</div>\';\n  const twoCol=x.state==="agrees"||x.state==="differs";\n  if(twoCol) body+=\'<table class="s771t"><colgroup><col style="width:38%"><col style="width:9%"><col style="width:44%"><col style="width:9%"></colgroup>\'\n      +\'<thead><tr><th>On the dealer\\\'s bill (scan)</th><th class="num">Qty</th><th>In Marg</th><th class="num">Qty</th></tr></thead><tbody>\'+x.lines.map(l=>s771line(x,l)).join(\'\')+\'</tbody></table>\';\n  else if(x.lines.length) body+=\'<table class="s771t"><thead><tr><th>\'+(x.state==="no_scan"?\'In Marg\':\'On the dealer\\\'s bill (scan)\')+\'</th><th class="num">Qty</th></tr></thead><tbody>\'+x.lines.map(l=>\'<tr><td class="sc"><div class="nm">\'+esc(l.scan||l.marg)+\'</div></td><td class="num sq">\'+esc(l.sq!=null?l.sq:(l.mq!=null?l.mq:\'\'))+\'</td></tr>\').join(\'\')+\'</tbody></table>\';\n  const foot=[];\n  if(x.scan_total!=null&&Math.abs(x.scan_total-x.marg_total)>2) foot.push(\'Bill total \'+s771rs(x.scan_total)+\' · Marg \'+s771rs(x.marg_total)+\'.\');\n  if(x.overflow) foot.push(\'Marg\\\'s export printed this bill\\\'s number into the item names; its lines are read here with the number cut off.\');\n  if(foot.length) body+=\'<div class="foot">\'+foot.map(esc).join(\' \')+\'</div>\';\n  if(x.scan_url) body+=\'<details class="s771scan" data-s771scan="\'+esc(x.scan_url)+\'" data-kind="\'+esc(x.scan_kind||\'\')+\'"><summary>📄 Show the scanned bill\'+(x.scan_no?\' (\'+esc(x.scan_no)+\')\':\'\')+\'</summary>\'\n      +\'<div class="s771paper"></div></details>\';\n  const op=(x.id in S771OPEN)?S771OPEN[x.id]:(S771.first===x.id);\n  return \'<details class="s771b\'+(flag?\' flag\':\'\')+\'" data-s771id="\'+x.id+\'"\'+(op?\' open\':\'\')+\'>\'+head+\'<div class="in">\'+body+\'</div></details>\';\n}\nfunction s771render(){\n  const J=S771, el=document.getElementById("s771"); if(!el) return;\n  if(!J.dealers.length){ el.innerHTML=\'\'; return; }\n  const nd=J.now.filter(x=>x.open).length; const fd=J.now.concat(J.open).find(x=>x.open); J.first=fd?fd.id:null;\n  let h=\'<h2 class="s769h">\'+esc(J.section)+\' bills — \'+s771mon(J.month)+\'</h2><div class="s771card"><div class="s771top"><div class="sub">Each \'+esc(J.section.toLowerCase())+\' dealer\\\'s bill: what the dealer\\\'s bill says (the scan) beside what Amir entered in Marg.\'\n    +(J.scans_ok?\'\':\' <span class="s769bad">The scans could not be read just now.</span>\')+\'</div>\'\n    +\'<div class="s771tally"><span><b>\'+J.now.length+\'</b> bills</span><span><b>\'+J.now.filter(x=>x.state==="agrees").length+\'</b> agree</span><span class="d"><b>\'+nd+\'</b> with a line to settle</span></div></div>\';\n  h+=\'<div class="s771sect">This month</div>\'+(J.now.length?J.now.map(s771bill).join(\'\'):\'<div class="sub">No bill from these dealers this month yet.</div>\');\n  if(J.open.length) h+=\'<div class="s771sect">Still open from earlier months (\'+J.open.length+\')</div><div class="sub" style="margin-bottom:6px">A bill stays here until every differing line is settled — Marg fixed (the next export shows it) or cleared by you.</div>\'+J.open.map(s771bill).join(\'\');\n  if(J.settled.length) h+=\'<div class="s771sect">Settled earlier</div><div class="sub">\'+J.settled.map(s=>\'Bill \'+esc(s.no)+\' (\'+esc(s769dd(s.date))+\') agrees\').join(\' · \')+\'</div>\';\n  h+=\'<span class="msg" id="s771msg"></span><div class="legend"><b>How a line is judged:</b> the size, the side (left / right), the brand and the quantity must all match. A scan word the reader got wrong is settled by the bill\\\'s own Marg line and shown only as a grey note. <b>Amir fixes Marg</b> puts one tap job on Amir\\\'s card; the line clears by itself when the next Marg export shows the fix.</div></div>\';\n  el.innerHTML=h;\n}\nfunction s771load(){\n  return fetch(SCP+"/api/bills?section=Orthotics&_="+Date.now(),{cache:"no-store"}).then(r=>r.json()).then(j=>{ if(!j.ok) throw new Error(j.message||j.error); S771=j; s771render(); })\n    .catch(e=>{ const el=document.getElementById("s771"); if(el) el.innerHTML=\'<div class="facts err">The orthotic bills could not be read (\'+esc(e.message||"no answer")+\'). Nothing else on this page is affected.</div>\'; });\n}\ndocument.addEventListener("toggle", e=>{\n  const d=e.target; if(!(d instanceof HTMLDetailsElement)) return;\n  if(d.classList.contains("s771b")){ S771OPEN[d.getAttribute("data-s771id")]=d.open; return; }\n  const u=d.getAttribute("data-s771scan"); if(!u||!d.open) return;\n  const p=d.querySelector(".s771paper"); if(!p||p.dataset.done) return; p.dataset.done="1";\n  const k=d.getAttribute("data-kind");\n  p.innerHTML=(k==="image"?\'<div class="pic"><img alt="The scanned bill" src="\'+esc(u)+\'"></div>\':(k==="pdf"?\'<iframe title="The scanned bill" src="\'+esc(u)+\'"></iframe>\':\'\'))\n    +\'<div class="act"><a class="b ghost" href="\'+esc(u)+\'" target="_blank" rel="noopener">Open full size in a new tab</a></div>\';\n}, true);\ndocument.addEventListener("click", async e=>{\n  const a=e.target.closest("[data-s771act]"); if(!a) return;\n  e.preventDefault(); if(a.disabled) return; a.disabled=true;\n  const j=await post(SCP+"/api/bills/mark",{bill:+a.getAttribute("data-s771bill"),key:a.getAttribute("data-s771key"),action:a.getAttribute("data-s771act")});\n  const y=window.scrollY; await s771load(); window.scrollTo(0,y); say("s771msg", j);\n});\ns771load();\n'
TAIL = '    audit(con, c["id"], "hand", dict(n=n, change=ch, skip=bool(sk)), _who(u))\n    con.commit()\n    return jsonify(ok=True)\n'
EDITS = {
    "section_count.py": [
        ('VERSION = "1.1"\nKIT = "S769_STOCK_HUB_COUNTS"                              # v1.0 was S768_SECTION_COUNT\n',
         'VERSION = "1.2"\nKIT = "S771_ORTHOTIC_BILLS"                                # v1.1 S769_STOCK_HUB_COUNTS, v1.0 S768_SECTION_COUNT\n'),
        ("    hf = hand_flags(con, items)\n",
         "    hf = hand_flags(con, items)\n    bf = bill_flags(con, section, items)                       # S771: an open difference on a dealer's bill\n"),
        ("        if it in hf:\n            lv, why = max(lv, 1), why + [hf[it]]\n",
         "        if it in hf:\n            lv, why = max(lv, 1), why + [hf[it]]\n        if it in bf:\n            lv, why = max(lv, bf[it][0]), why + [bf[it][1]]\n"),
        (TAIL, TAIL + PY_BLOCK),
    ],
    "stock_hub.html": [
        ("@media (max-width:700px){.s769g{grid-template-columns:1fr}.s769st{grid-template-columns:1fr 1fr}}\n",
         "@media (max-width:700px){.s769g{grid-template-columns:1fr}.s769st{grid-template-columns:1fr 1fr}}\n" + CSS_BLOCK),
        ('<div id="s769top"><div class="facts">Loading the counts\u2026</div></div>\n',
         '<div id="s769top"><div class="facts">Loading the counts\u2026</div></div>\n<div id="s771"></div>\n'),
        ("s769top();\n</script></body></html>", "s769top();\n" + JS_BLOCK + "</script></body></html>"),
    ],
}


def md5(b):
    return hashlib.md5(b).hexdigest()


def main(fin, out):
    os.makedirs(out, exist_ok=True)
    for name, edits in EDITS.items():
        b = open(os.path.join(fin, name), "rb").read()
        if md5(b) != FROM[name]:
            print("REFUSED: %s is %s, not its FROM pin %s" % (name, md5(b)[:8], FROM[name][:8]))
            return 2
        t = b.decode("utf-8")
        if name == "section_count.py" and not t.endswith(TAIL):
            print("REFUSED: section_count.py does not end where this kit appends")
            return 2
        for old, new in edits:
            if t.count(old) != 1:
                print("REFUSED: %s: an anchor matches %d times: %r" % (name, t.count(old), old[:60]))
                return 2
            t = t.replace(old, new)
        nb = t.encode("utf-8")
        open(os.path.join(out, name), "wb").write(nb)
        print("built %s %s -> %s" % (name, FROM[name][:8], md5(nb)[:8]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1], sys.argv[2]))
